	/*
	 * Metoda za vracanje otpremnica
	 */
	public List<Perso> vracanjeOtpremnice(String ean, String user) {
		logger.info("***********************BEGIN vracanjeOtpremnice***********************");
		// List<Perso> otpremniceZaVracanje = persoRepo.findByEan(ean);
		List<Perso> otpremniceZaVracanje = persoRepo.findByOPxcode(ean);
		LocalDateTime currentDateAndTime = LocalDateTime.now();
		logger.info("***********************otpremniceZaVracanje size*********************** {}", otpremniceZaVracanje.size());
		otpremniceZaVracanje.forEach((o) -> {
				o.setOPxcode(null); // dodatak
				o.setStatus(statusReturn); // vracanje statusa na VRACENO
				o.setOStatus(status_Otp_opened);
				o.setOPaket(null);
				o.setODatum(currentDateAndTime);
//			o.setOStampa("2"); // stampa status vracena
				o.setOStampa(CS.PRINTED_RETURNED.getId()); // stampa status vracena
				o.setStampaXlsx(0); // vracanja na ponovnu stampu xlsx-a za postu
				if (o.getPackagedef().equalsIgnoreCase("000"))
					o.setOPaket("Redovna_R");
				else
					o.setOPaket("Obnova_R");
				if (o.getOBranch().equalsIgnoreCase("XXXX")) // Vracanje na Branch za poslate na kucnu adresu
				{
					o.setOBranch(o.getBranchExport());
				}
		});
		for (Perso otpremnica : otpremniceZaVracanje) {
			persoRepo.save(otpremnica);
		}
		logger.info("***********************BEGIN LOGING after vracanjeOtpremnice ***********************");
		if (otpremniceZaVracanje.size() > 0)
			persoHistoryService.saveLog(otpremniceZaVracanje.get(0), currentDateAndTime,
					otpremniceZaVracanje.get(0).getODatum(), user, "VracanjeOtpremnice"); // sacuva prvi

		return otpremniceZaVracanje;
	}
