	public Perso fileRowToObject(String line, String fileName, String createdAt) {
		LocalDateTime currentDateAndTime = LocalDateTime.now();
		DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
		String batchID = currentDateAndTime.format(formatter);

		String tip = fileName.substring(4, 5).toUpperCase();
		Perso sia = new Perso();
		switch (tip) {
		case "C":
			// CLIENT
			sia.setSearchCode(line.substring(0, 6).trim());
			sia.setClientAccount(line.substring(488, 507).trim());
			// CARD
			sia.setCardNumber(line.substring(104, 120).trim());
			sia.setCardFirstFour(line.substring(104, 108).trim());
			sia.setCardLastFour(line.substring(22, 26).trim());
			sia.setCardValidFrom(line.substring(27, 32).trim());
			sia.setCardValidUntil(line.substring(33, 38));
			sia.setCardCvc(line.substring(93, 101).trim());
			sia.setCardEmboss1(line.substring(39, 65).trim());
			sia.setCardEmboss2(line.substring(66, 92).trim());
			// DELIVERY
			sia.setDeliveryTo(line.substring(250, 285).trim());
			sia.setDeliveryToClient(line.substring(286, 321).trim());
			sia.setDeliveryAddress2(line.substring(322, 357).trim());
			sia.setDeliveryStreet(line.substring(358, 398).trim());
			sia.setDeliveryCity(line.substring(399, 434).trim());
			sia.setDeliveryPostcode(line.substring(435, 445).trim());
			sia.setDeliveryCountry(line.substring(446, 481).trim());
			// BRANCH
			sia.setBranchImport(line.substring(482, 487));
			// FILE
			sia.setFileImportName(fileName);
			sia.setFileImportTime(currentDateAndTime);
			sia.setStatus(statusService.getStatusByStatus(statusPreImported).getStatus());
			sia.setUpdatedBy("SYSTEM"); // STATUS
			sia.setUpdatedAt(currentDateAndTime); // STATUS
			// META
			sia.setEan(line.substring(488, 488 + 8) + String.format("%05d", ThreadLocalRandom.current().nextInt(100_000)));
			sia.setBatchid(batchID);
			sia.setType(String.valueOf(fileName.charAt(4)));
			sia.setDeliverymethode(fileName.substring(9, 11));
			sia.setPackagedef(fileName.substring(12, 15));
			sia.setMagneticStripTrackOne(line.substring(102, 180).trim());
			sia.setMagneticStripTrackTwo(line.substring(180, 220).trim());
			sia.setPinBlock(line.substring(560, 576).trim());
			sia.setRequestAction(line.substring(577, 578).trim());
			sia.setICvv(line.substring(579, 582).trim());

			// Ovo je sporiji nacin
			/*
			 * long primaryAccountNumber = Long.parseLong(sia.getCardNumber());
			 * CardDestination cdo = cds.getBranchWithProcedure(primaryAccountNumber);
			 * sia.setBranchExport(cdo.getDestinationBranch());
			 * sia.setCardTypeName(cdo.getCardTypeName());
			 * sia.setClientNumber(cdo.getClientNumber());
			 */
			break;

		case "P":
			sia.setCardNumber(line.substring(7, 23));
			sia.setSearchCode(line.substring(0, 6).trim());
			sia.setPinBlock(line.substring(30, 46).trim());
			sia.setCardValidUntil(line.substring(28, 30) + "/" + line.substring(26, 28));
			sia.setCardEmboss1(line.substring(99, 125).trim());
			sia.setCardFirstFour(line.substring(7, 11).trim());
			sia.setCardLastFour(line.substring(19, 23).trim());
			sia.setCardEmboss2(line.substring(284, 310).trim());
			sia.setDeliveryTo(line.substring(64, 99).trim());
			sia.setDeliveryToClient(line.substring(99, 134).trim());
			sia.setDeliveryAddress2("");
			sia.setDeliveryStreet(line.substring(169, 204).trim());
			sia.setDeliveryCity(line.substring(204, 239).trim());
			sia.setDeliveryPostcode(line.substring(239, 249).trim());
			sia.setDeliveryCountry(line.substring(249, 284).trim());
			sia.setBranchImport(line.substring(319, 324));
			sia.setFileImportName(fileName);
			sia.setFileImportTime(currentDateAndTime);
			sia.setStatus(statusService.getStatusByStatus(statusPreImported).getStatus());
			sia.setEan("");
			sia.setBatchid(batchID);
			sia.setType(String.valueOf(fileName.charAt(4)));
			sia.setDeliverymethode(fileName.substring(9, 11));
			sia.setPackagedef(fileName.substring(12, 15));
			/*
			 * long primaryAccountNumber1 = Long.parseLong(sia.getCardNumber());
			 * CardDestination cd = cds.getBranchWithProcedure(primaryAccountNumber1);
			 * sia.setBranchExport(cd.getDestinationBranch());
			 * sia.setClientNumber(cd.getClientNumber());
			 * sia.setClientAccount(cd.getAccountNumber());
			 * sia.setCardTypeName(cd.getCardTypeName());
			 */
			break;
		default:
			// BACI EXCEPTION
		}

		return sia;

	}

