@Service
public class CardRegistrationServiceImpl implements CardRegistrationService {

    private static final Logger logger = LoggerFactory.getLogger(CardRegistrationServiceImpl.class);

    @Autowired
    private PersoRepository persoRepo;

    @Autowired
    private CardRegistrationHistoryRepository cardHistoryRepo;

    @Autowired
