    private static final String EMAIL_DOMAIN = "@unicreditgroup.rs";

    @Override
    public List<Perso> getAllShipmentForMyBranch(String department) {
        logger.info("Fetching all shipments for branch: {}", department);
        List<Perso> listPerso = persoRepo.findByOBranchAndOStampaAndStatusAndBranchDeliveryIsNullOrderByODatumDesc(department,  CS.PRINTED.getId(), CS.SENT.getId());
        //List<Perso> listPerso = persoRepo.findMyShipment(department, department,  PRINTED, SENT);
        listPerso.forEach(this::maskedCardNumber);	
        return listPerso;
    }

    @Override
    public Boolean acceptAllShipment(List<ShipmentDTO> shipmentDtoList, String userName, String branch) {
        for (ShipmentDTO shipmentDto : shipmentDtoList) {
            Optional<Perso> optionalPerso = persoRepo.findById(shipmentDto.getId());
            if (optionalPerso.isPresent()) {
                Perso p = optionalPerso.get();
                logger.debug("Processing Perso: {}", p);

                p.setOBranch(shipmentDto.getOBranch());
                p.setBranchDelivery(shipmentDto.getOBranch());
                p.setOPxcode(shipmentDto.getOPxcode());
                p.setUpdatedBy(userName);
                p.setUpdatedAt(LocalDateTime.now());
                p.setStatus(CS.RECEIVED.getId());
                persoRepo.save(p);

                CardRegistrationHistory ch = createCardHistory(shipmentDto.getId(), CS.RECEIVED.getId(), CS.RECEIVED.getText(), userName, branch);
                cardHistoryRepo.save(ch);
            } else {
                logger.warn("Perso with ID: {} not found", shipmentDto.getId());
            }
        }
        return true;
    }

    @Override
    public Boolean acceptShipment(ShipmentDTO shipmentDto, String userName, String department) {
        return processShipment(shipmentDto, CS.RECEIVED, userName, department);
//        return processShipment(shipmentDto, RECEIVED, userName);
    }

    @Override
    public Boolean redirectShipment(ShipmentDTO shipmentDto, String department,String userName) {
        /* ÄŒuvamo log za izgubljene kartice --> Redirekcija */
        ShipmentLog log = shipmentMapper.shipmentToShipmentLog(shipmentDto);
        log.setUpdatedBy(userName);
        log.setUpdatedByBranch(department);
        log.setUpdatedAt(LocalDateTime.now());
        log.setStatusShipment(CS.REDIRECTED.getText());
        shipmentLogRepository.save(log);
        return processShipment(shipmentDto, CS.REDIRECTED , userName,department);
//        return processShipment(shipmentDto, REDIRECTED, userName);
    }
    
    @Override
    public Boolean rejectShipment(ShipmentDTO shipmentDto, String department, String userName) {
