	public List<PersoDTO> importPersosAndSave() throws IOException, FileImportException {

		List<FileMetadata> filesMeta = fileService.getAllUnimportedFiles();
		List <Perso> persosList = new ArrayList<>();

		for (FileMetadata meta : filesMeta) {
			logger.info("***********************BEGIN IMPORT SIA ***********************");
			int numberOfRowInFile = 0;
			try (BufferedReader reader = new BufferedReader(new FileReader(meta.getFile()))) {
				String line;
				while ((line = reader.readLine()) != null) {
					Perso p = persoRepo.save(persoMapper.dtoToEntity(fileRowToObject(line, meta.getFile().getName(), meta.getCreatedAt())));
					persosList.add(p);
					numberOfRowInFile++;
				}
				logger.info("Filename: {}, number of line: {}", meta.getFileName(), numberOfRowInFile);

			} catch (Exception e) {
				logger.error(e.getLocalizedMessage());
			}

			int numberOfRowInDB = persoRepo.numberOfRowByFilenameInPersoTbl(meta.getFileName(),statusImported);
			logger.info("Filename: {}, number of row in DB: {}", meta.getFileName(), numberOfRowInDB);

			if (numberOfRowInDB == numberOfRowInFile) {

				logger.info("The number of lines and rows are the same.");
				String toArchive = fileService.createArchiveStructureIfNotExist();
				fileService.moveFileToArchive(toArchive, meta.getFileName());

			} else {
				logger.error("The number of lines and rows are NOT the same.");
				persosList.removeIf(t -> t.getFileImportName().equals(meta.getFileName()));
				persoRepo.deleteByImportDateAndFilename(meta.getFileName(),statusImported);
			}
			numberOfRowInFile = 0;
			logger.info("***********************END*****************************");
		}
		if (persosList.size()>0){
				logger.info("Slanje maila posle importa fajlova!");
				mailService.sendEMailPersoByStatus(statusImported, "1");
		}

		return persoMapper.entityToDtoList(persosList);
	}

	public List<Perso> exportFiles() throws IOException {
		logger.info("***********************BEGIN EXPORT***********************");

		String statusForExport = statusService.getStatusByStatus(statusImported).getStatus();
		List<Perso> persoList = new ArrayList<>();
		List<Perso> persoListDatabase = persoRepo.findByStatusOrderByBranchExportAscCardNumberAsc(statusForExport);
		logger.info("***Number of lines for export: {}", persoListDatabase.size());

        LocalDateTime currentDateAndTime = LocalDateTime.now();

		DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HHmmss");
		String pinFileName = currentDateAndTime.format(formatter);
		pinExportFile = "\\PIN " + pinFileName + ".dat";


		// String statusExported= "1";
		String statusMail = "1";
		for (Perso p : persoListDatabase) {
			writeToFile(pathTo, p);
			/* Promene na perso posle exporta */
			p.setFileExportName(p.getFileImportName());
			p.setFileExportTime(currentDateAndTime);
			p.setStatus(statusService.getStatusByStatus(statusExported).getStatus());
			// p.setStatus(statusExported);
			persoList.add(p);
			persoRepo.save(p);
		}
		if (persoList != null && persoList.size() > 0) {
			logger.info("Sending email on status export: {}, with status email: {}", statusExported, statusMail);
			mailService.sendEMailPersoByStatus(statusExported, statusMail);
		}

		return persoList;
	}
