			FileOutputStream fileOutStream = null;
			String firstSix = StringUtils.substring(perso.getCardNumber(), 0, 8);
			String lastFour = StringUtils.right(perso.getCardNumber(), 4);
			String hiddenCard = rightpad(firstSix, 8) + "***" + rightpad(lastFour, 4);
			;
			/* Formiranje fajla (generisanjeHSMFajla) za export */
			String red = "P" +
					rightpad(nvl(perso.getCardNumber(), " "), 16) +
