	 * codoba
	 */
	public List<Perso> sendOtpremnice(String branch, String px, String user) {
		logger.info("***********************BEGIN sendOtpremnice*********************** branch" + branch);
		logger.info("***********************BEGIN sendOtpremnice*********************** status_Otp_opened"
				+ status_Otp_opened);
		System.out.println(" sendOtpremnice user: " + user);
		// List<Otpremnice> otpremniceDatabase = persoRepo.findOtpremnice();
		List<Perso> otvoreneOtpremnice = persoRepo.findByOBranchAndOStatusOrderByOBranchAsc(branch, status_Otp_opened);
		LocalDateTime currentDateAndTime = LocalDateTime.now();
		logger.info(
				"***********************otvoreneOtpremnice size***********************" + otvoreneOtpremnice.size());
		if (px == null || px.trim().equalsIgnoreCase("")) { // Za prazne PX ne radim update
			logger.info("***********************sendOtpremnice prazan PX za branch :" + branch);
		} else {
			otvoreneOtpremnice.forEach((o) -> {
				o.setStatus(statusSent); // postavljanje statusa perso na sent
				o.setEan(px); // postavljanje ean-a na osnovu Stevinog trigera TRIGGER
								// UCBCARDN.perso_otpremnice_after_update
				o.setOStatus(status_Otp_closed); // postavljanje statusa otpremnice na closed
				// o.setOPxcode(px); // vec uneto kroz fillPxCodeOtpremnice
				o.setODatum(currentDateAndTime);
				o.setStampaXlsx(0); // vracanja na ponovnu stampu xlsx-a za postu
			});
			for (Perso otpremnica : otvoreneOtpremnice) {
				persoRepo.save(otpremnica);

				CardRegistrationHistory c = new CardRegistrationHistory();
				c.setPersoId(otpremnica.getId());
				c.setStatusId(statusSent);
				c.setStatusDescription("Poslato");
				c.setUpdatedBy(user);
				c.setUpdatedAt(currentDateAndTime);

				cardRegistrationHistoryService.save(c);
			}

			logger.info("***********************BEGIN LOGING after sendOtpremnice***********************");
			if (otvoreneOtpremnice.size() > 0)
				persoHistoryService.saveLog(otvoreneOtpremnice.get(0), currentDateAndTime,
						otvoreneOtpremnice.get(0).getODatum(), user, "SlanjePaketa"); // sacuva prvi
		}
		return otvoreneOtpremnice;
	}

