	private static String rightpad(String text, int length) {
		return String.format("%-" + length + "." + length + "s", text);
	}

	void writeToFile(String pathTo, Perso perso) throws IOException {

		if (perso.getType().equalsIgnoreCase("c")) {
			String fileName = perso.getFileImportName() + ".dat";
			String filePath = pathTo + File.separator + fileName;
			logger.info("***Export CARD file with name: {}, on location: {} ", fileName, pathTo);
			Path p = Paths.get(filePath);
			File file = new File(filePath);
			if (!file.exists()) {
				file.createNewFile();
			}
			FileOutputStream fileOutStream = null;
			/* Formiranje fajla (generisanjeHSMFajla) za export */
			String normalPan = perso.getCardNumber();
			String val = "4";
			String spacePan = normalPan.replaceAll("(.{" + val + "})", "$1 ").trim();

			String red = rightpad(nvl(perso.getSearchCode(), ""), 6) + "$" + rightpad(spacePan, 19) + "@"
					+ rightpad(nvl(perso.getCardValidFrom(), ""), 5) + "@"
					+ rightpad(nvl(perso.getCardValidUntil(), ""), 5) + "@"
					+ rightpad(nvl(perso.getCardEmboss1(), ""), 26) + "@"
					+ rightpad(nvl(perso.getCardEmboss2(), ""), 26) + "@" + rightpad(nvl(perso.getCardCvc(), ""), 8)
					+ "\"" +
//					rightpad(nvl(perso.getCardLastFour(),""), 4) + " " +
//					rightpad(nvl(perso.getCardCvc(),""), 3) + "\"" +
					rightpad(nvl(perso.getMagneticStripTrackOne(), ""), 78)
					+ rightpad(nvl(perso.getMagneticStripTrackTwo(), ""), 39) + "#"
					+ rightpad(nvl(perso.getEan(), ""), 13) + "@" + rightpad("", 15) + "@" + // TITLE/SALUTATION
					rightpad(nvl(perso.getDeliveryTo(), ""), 35) + "@" + // name
					rightpad(nvl(perso.getDeliveryToClient(), ""), 35) + "@"
					+ rightpad(nvl(perso.getDeliveryAddress2(), ""), 35) + "@"
					+ rightpad(nvl(perso.getDeliveryStreet(), ""), 40) + "@"
					+ rightpad(nvl(perso.getDeliveryCity(), ""), 35) + "@"
					+ rightpad(nvl(perso.getDeliveryPostcode(), ""), 10) + "@"
					+ rightpad(nvl(perso.getDeliveryCountry(), ""), 35) + "@"
					+ rightpad(nvl(perso.getBranchExport(), ""), 5) + "@"
					+ rightpad(nvl(perso.getClientAccount(), ""), 19) + "@"
					+ rightpad(nvl(perso.getCardLastFour(), ""), 30) + "@" + // PRODUCT DESCRIPTION #1
					rightpad("", 20) + "@" + // PRODUCT DESCRIPTION #2
					rightpad(nvl(perso.getPinBlock(), ""), 16) + "@" + rightpad(nvl(perso.getRequestAction(), ""), 1)
					+ "@" + rightpad(nvl(perso.getICvv(), ""), 3) + "@" + rightpad("", 20) + // RESERVED FOR FUTURE USE
					"#END#";

			logger.info("***Absolute path: {}", p.toAbsolutePath());

			try (OutputStream out = new BufferedOutputStream(Files.newOutputStream(p, StandardOpenOption.APPEND))) {
				out.write(red.getBytes());
				out.write("\r\n".getBytes());
				/* Arhivu export fajlova */
				String toArchive = fileService.createExportedArchiveStructureIfNotExist();
				fileService.copyFileToDestination(p.toAbsolutePath().toString(), toArchive);

			} catch (IOException e) {
				System.err.println(e);
			} catch (Exception e) {
				e.printStackTrace();
			} finally {
				try {
					if (fileOutStream != null) {
						fileOutStream.close();
					}
				} catch (Exception e) {
					e.printStackTrace();
				}
			}

		} else if (perso.getType().equalsIgnoreCase("p")) {
			String filePath = pathTo + File.separator + pinExportFile;
			logger.info("***Export PIN file with name: {}, on location: {} ", pinExportFile, pathTo);
			Path p = Paths.get(filePath);
			File file = new File(filePath);
			if (!file.exists()) {
				file.createNewFile();
			}
			FileOutputStream fileOutStream = null;
			String firstSix = StringUtils.substring(perso.getCardNumber(), 0, 8);
			String lastFour = StringUtils.right(perso.getCardNumber(), 4);
			String hiddenCard = rightpad(firstSix, 8) + "***" + rightpad(lastFour, 4);
			;
			/* Formiranje fajla (generisanjeHSMFajla) za export */
			String red = "P" + rightpad(nvl(perso.getCardNumber(), " "), 16)
					+ rightpad(nvl(perso.getCardEmboss1(), " "), 27) + rightpad(nvl(perso.getCardEmboss2(), " "), 27)
					+ rightpad(nvl(perso.getCardTypeName(), " "), 35) + rightpad(nvl(perso.getClientNumber(), " "), 11)
					+ rightpad(nvl(hiddenCard, " "), 18) + rightpad(nvl(perso.getBranchExport(), " "), 6)
					+ rightpad(nvl(perso.getDeliveryStreet(), " "), 73) + rightpad(nvl(perso.getPinBlock(), " "), 16);
			logger.info("***Absolute path: {}", p.toAbsolutePath());
			try (OutputStream out = new BufferedOutputStream(Files.newOutputStream(p, StandardOpenOption.APPEND))) {
				out.write(red.getBytes());
				out.write("\r\n".getBytes());
			} catch (IOException e) {
				System.err.println(e);
			} catch (Exception e) {
				e.printStackTrace();
			} finally {
				try {
					if (fileOutStream != null) {
						fileOutStream.close();
					}
				} catch (Exception e) {
					e.printStackTrace();
				}
			}
		} else {
			logger.error("Invalid card type!!!");
		}

		logger.info("***********************END EXPORT***********************");
	}

	public static String nvl(String value, String alternateValue) {
		if (value == null)
			return alternateValue;
		return value;
	}

	public Perso fileRowToObject(String line, String fileName, String createdAt) {
