					+ "\"" +
//					rightpad(nvl(perso.getCardLastFour(),""), 4) + " " +
//					rightpad(nvl(perso.getCardCvc(),""), 3) + "\"" +
					rightpad(nvl(perso.getMagneticStripTrackOne(), ""), 78)
					+ rightpad(nvl(perso.getMagneticStripTrackTwo(), ""), 39) + "#"
					+ rightpad(nvl(perso.getEan(), ""), 13) + "@" + rightpad("", 15) + "@" + // TITLE/SALUTATION
					rightpad(nvl(perso.getDeliveryTo(), ""), 35) + "@" + // name
					rightpad(nvl(perso.getDeliveryToClient(), ""), 35) + "@"
					+ rightpad(nvl(perso.getDeliveryAddress2(), ""), 35) + "@"
